module.exports=[82665,a=>{"use strict";let b=[{slug:"amoled",title:"AMOLED",desc:"Layar lebih hidup, kontras lebih tinggi, dan lebih hemat daya.",kind:"Teknologi layar",example:"Contoh: Galaxy S25 Ultra, Pixel 8",audience:["smartphones"],icon:"▣",artClass:"gradient-screen",chapters:[{heading:"Apa itu AMOLED?",body:"AMOLED (Active-Matrix Organic Light-Emitting Diode) adalah teknologi layar di mana setiap piksel menyala dengan cahayanya sendiri. Karena tidak butuh backlight di belakang layar, hitam bisa benar-benar gelap dan warna terlihat lebih hidup dibanding layar LCD biasa."},{heading:"Kenapa penting untukmu?",body:"Kontras yang tinggi membuat video dan foto jauh lebih dramatis. Piksel yang mati saat menampilkan warna hitam juga menghemat daya — makin banyak konten gelap, makin hemat baterai."},{heading:"Kekurangannya",body:"Bahan organik pada piksel bisa mengalami burn-in bila layar menampilkan elemen statis dalam waktu lama. Pilih AMOLED yang sudah dilengkapi teknologi pengatur piksel modern untuk meminimalkan risiko ini."}]},{slug:"ltpo",title:"LTPO",desc:"Refresh rate adaptif untuk performa dan daya tahan baterai yang lebih baik.",audience:["smartphones"],kind:"Teknologi layar",example:"Contoh: iPhone 16 Pro, Galaxy S25 Ultra",icon:"▤",artClass:"layers",chapters:[{heading:"Teknologi refresh rate adaptif",body:"LTPO (Low-Temperature Polycrystalline Oxide) memungkinkan layar mengubah refresh rate secara dinamis — dari 1 Hz hingga 120 Hz. Layar diam mungkin hanya berjalan 1–10 Hz, sedangkan saat scrolling game turun naik mengikuti konten."},{heading:"Penghematan baterai yang nyata",body:"Refresh rate rendah saat aktivitas statis berarti panel lebih jarang 'bangun'. Kamu tetap mendapat kelancaran 120 Hz tanpa mengorbankan daya tahan baterai sepanjang hari."},{heading:"Biasa ditemukan di mana?",body:"LTPO biasanya ada di flagship premium seperti iPhone Pro dan Galaxy Ultra. Kalau refresh rate adaptif adalah prioritasmu, periksa apakah panel perangkat mendukung LTPO, bukan sekadar 120 Hz statis."}]},{slug:"peba",title:"PEBA",desc:"Bahan midsole premium yang lebih ringan, empuk, dan responsif.",kind:"Material sepatu",example:"Contoh: Nike ZoomX Vaporfly, Saucony Endorphin",audience:["shoes"],icon:"◌",artClass:"foam",chapters:[{heading:"Apa itu PEBA?",body:"PEBA (Polyether Block Amide) adalah bahan polimer yang dipakai pada midsole sepatu lari dan basket kelas atas. Dibanding EVA atau TPU konvensional, PEBA jauh lebih ringan sekaligus lebih elastis."},{heading:"Kenapa lari terasa lebih cepat",body:"Sifat elastis PEBA mengembalikan energi dengan lebih efisien, sehingga setiap langkah terasa 'memantulkan'. Bahan ini juga lebih empuk tanpa menambah bobot — kombinasi ideal untuk pelari jarak jauh."},{heading:"Kekurangannya",body:"Harganya lebih mahal karena proses produksinya kompleks. Beberapa varian PEBA juga bisa terasa kurang stabil di tikungan, sehingga biasanya dipadukan dengan plate atau frame kaku."}]},{slug:"carbon-fiber",title:"Carbon Fiber",desc:"Material kuat, ringan, dan fleksibel untuk performa maksimal.",kind:"Material sepatu & laptop",example:"Contoh: pelat karbon Nike Alphafly, rangka laptop premium",audience:["shoes","laptops"],icon:"✥",artClass:"carbon",chapters:[{heading:"Serat yang mengubah desain",body:"Carbon fiber adalah material dari serat karbon yang disusun dan diawetkan dengan resin. Hasilnya sangat kaku dan ringan — itulah kenapa ia dipakai pada sepatu lari, rangka laptop, hingga bodi mobil balap."},{heading:"Peran pada sepatu dan laptop",body:"Di sepatu lari, plate carbon fiber bekerja seperti tuas yang mendorong kaki maju dan memangkas energi. Di laptop, cover carbon fiber memberi kekuatan dengan bobot jauh lebih ringan dari aluminium."},{heading:"Kenapa mahal?",body:"Proses produksinya bersifat kompleks dan setiap lembar serat harus ditata presisi. Itu sebabnya produk carbon fiber premium dijual dengan harga lebih tinggi — sebagai imbalannya kamu dapat rasio kekuatan-berat terbaik yang ada."}]},{slug:"chip-3nm",title:"Chip 3nm",desc:"Chipset generasi fabrikasi 3 nanometer: lebih kencang sekaligus lebih hemat daya.",kind:"Teknologi chipset",example:"Contoh: A18 Pro, Snapdragon 8 Elite",audience:["smartphones"],icon:"⚙",artClass:"layers",chapters:[{heading:"Apa arti angka 3nm?",body:"Angka nanometer (nm) menunjukkan ukuran transistor di dalam chip — makin kecil, makin banyak transistor yang muat di ruang yang sama. Chip 3nm seperti A18 Pro dan Snapdragon 8 Elite memadatkan miliaran transistor lebih banyak dibanding generasi 5nm atau 7nm."},{heading:"Kenapa penting untukmu?",body:"Transistor yang lebih rapat berarti dua hal sekaligus: performa lebih tinggi untuk game dan AI, plus konsumsi daya lebih rendah untuk tugas yang sama. Itu sebabnya flagship terbaru terasa lebih kencang tanpa baterai yang lebih boros."},{heading:"Batasannya",body:"Fabrikasi 3nm mahal dan rumit, jadi hanya dipakai di chip flagship. Chip kelas menengah masih memakai 4–6nm — tetap kencang untuk harian, hanya kalah efisien di beban berat."}]},{slug:"kamera-periskop",title:"Kamera Periskop",desc:"Lensa zoom yang dilipat di dalam bodi agar bisa memotret jauh tanpa bodi tebal.",kind:"Teknologi kamera",example:"Contoh: Galaxy S25 Ultra, iPhone 15 Pro Max",audience:["smartphones"],icon:"◉",artClass:"gradient-screen",chapters:[{heading:"Apa itu kamera periskop?",body:"Kamera periskop membelokkan cahaya 90 derajat lewat prisma, lalu melewatkannya sepanjang bodi ponsel sebelum sampai ke sensor. Trik ini memberi ruang untuk lensa zoom optik 5x atau lebih tanpa membuat bodi HP menebal."},{heading:"Beda dengan zoom digital",body:"Zoom optik memperbesar lewat lensa sehingga detail tetap tajam, sedangkan zoom digital hanya memotong dan memperbesar piksel. Klaim seperti 100x Space Zoom adalah kombinasi optik + digital + AI — makin jauh, makin besar peran software."},{heading:"Batasannya",body:"Lensa periskop butuh cahaya cukup; di kondisi gelap hasilnya bisa kalah dari kamera utama. Modulnya juga mahal dan memakan ruang, jadi hanya ada di varian Ultra/Pro Max."}]},{slug:"rangka-titanium",title:"Rangka Titanium",desc:"Bodi ponsel dari titanium: sekuat baja tapi jauh lebih ringan.",kind:"Material bodi",example:"Contoh: iPhone 16 Pro, Galaxy S25 Ultra",audience:["smartphones"],icon:"⬢",artClass:"carbon",chapters:[{heading:"Kenapa titanium?",body:"Titanium punya rasio kekuatan-berat yang sangat baik — hampir sekuat baja tapi sekitar 40% lebih ringan. Flagship seperti iPhone 16 Pro dan Galaxy S25 Ultra memakainya agar bodi besar tetap nyaman digenggam."},{heading:"Kelebihan yang terasa",body:"Bobot turun jelas dibanding rangka stainless steel, sekaligus lebih tahan bengkok dibanding aluminium biasa. Finishing-nya juga memberi kesan premium yang jadi ciri flagship."},{heading:"Batasannya",body:"Titanium sulit dibentuk dan mahal diproduksi, sehingga hanya muncul di varian termahal. Ia juga bukan anti-gores — tetap butuh case kalau kamu khawatir bodi lecet."}]},{slug:"kaca-pelindung",title:"Kaca Pelindung",desc:"Kaca layar yang diperkuat secara kimiawi agar tahan jatuh dan gores.",kind:"Material layar",example:"Contoh: Ceramic Shield (iPhone), Gorilla Armor (Galaxy S25 Ultra)",audience:["smartphones"],icon:"◇",artClass:"gradient-screen",chapters:[{heading:"Beda dengan kaca biasa",body:"Kaca pelindung seperti Ceramic Shield dan Gorilla Armor diperkuat lewat proses kimia yang menanamkan tekanan di permukaan. Hasilnya jauh lebih tahan retak saat jatuh dibanding kaca standar — meski memakai nama dagang berbeda, prinsipnya sama."},{heading:"Kenapa tetap butuh pelindung?",body:"Tahan jatuh bukan berarti anti-gores. Pasir dan debu di saku tetap bisa meninggalkan goresan halus. Kaca pelindung menaikkan batas aman, bukan menghilangkannya."},{heading:"Trade-off-nya",body:"Semakin keras kaca, biasanya semakin rentan pecah saat benturan titik tertentu — dan sebaliknya. Produsen menyeimbangkan kekerasan anti-gores dengan kelenturan anti-pecah di tiap generasi."}]},{slug:"wireless-charging",title:"Wireless Charging",desc:"Isi daya tanpa kabel lewat induksi magnet — praktis, termasuk MagSafe.",kind:"Teknologi daya",example:"Contoh: MagSafe (iPhone), Wireless PowerShare (Galaxy)",audience:["smartphones","laptops"],icon:"⚡",artClass:"foam",chapters:[{heading:"Cara kerjanya",body:"Charging pad mengalirkan arus ke kumparan yang menimbulkan medan magnet, lalu kumparan di dalam HP mengubahnya kembali jadi listrik. MagSafe di iPhone menambahkan magnet agar posisi kumparan selalu presisi."},{heading:"Kenapa praktis?",body:"Tinggal tempel tanpa colok-cabut kabel — cocok di meja kerja atau mobil. Galaxy bahkan bisa berbagi daya ke earbuds atau jam lewat Wireless PowerShare."},{heading:"Batasannya",body:"Lebih lambat dan lebih panas dibanding kabel, dan sebagian energi terbuang sebagai panas. Untuk isi cepat sebelum pergi, kabel + fast charging tetap juaranya."}]},{slug:"ip68",title:"IP68",desc:"Sertifikasi tahan debu dan air — dengan syarat dan batas yang jelas.",kind:"Ketahanan",example:"Contoh: iPhone 16 Pro, Galaxy S25 Ultra",audience:["smartphones"],icon:"💧",artClass:"gradient-screen",chapters:[{heading:"Arti angka 6 dan 8",body:"IP68 terdiri dari dua angka: 6 berarti kedap debu total, 8 berarti tahan direndam air tawar hingga kedalaman dan durasi tertentu sesuai uji lab (umumnya 1,5–6 meter selama 30 menit, tergantung merek)."},{heading:"Yang tidak dicover",body:"Uji lab memakai air tawar bersih dan kondisi statis — bukan air laut, kolam berklorin, atau air panas. Kerusakan akibat cairan juga umumnya tidak ditanggung garansi, jadi IP68 adalah jaring pengaman, bukan undangan berenang."},{heading:"Ketahanan yang menurun",body:"Segel anti-air bisa melemah seiring usia, benturan, dan servis. HP dua tahun yang masih berlabel IP68 belum tentu setahan saat baru keluar dari kotak."}]},{slug:"night-mode",title:"Night Mode",desc:"Foto malam yang terang berkat gabungan banyak frame dan AI.",kind:"Teknologi kamera",example:"Contoh: Pixel 8 Night Sight, iPhone Night mode",audience:["smartphones"],icon:"🌙",artClass:"gradient-screen",chapters:[{heading:"Cara kerjanya",body:"Night mode mengambil banyak foto dengan exposure berbeda dalam beberapa detik, lalu menggabungkannya lewat komputasi — seperti yang dipopulerkan Night Sight di Pixel. Hasilnya: foto malam yang terang tanpa flash."},{heading:"Kenapa jadi pembeda?",body:"Kualitas foto malam kini lebih ditentukan software dibanding ukuran sensor. Dua HP dengan megapiksel sama bisa berbeda jauh hasilnya hanya karena racikan night mode-nya."},{heading:"Batasannya",body:"Objek bergerak cepat bisa blur karena butuh waktu ambil frame, dan hasilnya kadang terlihat terlalu 'dipoles' dibanding suasana aslinya. Untuk aksi cepat, mode normal + cahaya cukup tetap lebih baik."}]},{slug:"fast-charging",title:"Fast Charging",desc:"Isi daya berdaya besar agar penuh dalam puluhan menit.",kind:"Teknologi daya",example:"Contoh: Galaxy S25 Ultra 45W, iPhone 20W+ via USB-C",audience:["smartphones","laptops"],icon:"🔌",artClass:"foam",chapters:[{heading:"Arti angka watt",body:"Angka watt (mis. 45W) menunjukkan kecepatan isi maksimal yang didukung HP — tapi hanya tercapai dengan charger dan kabel yang kompatibel. Galaxy S25 Ultra mendukung 45W, sedangkan iPhone mengisi sekitar 20W ke atas lewat USB-C."},{heading:"Kenapa tidak selalu maksimal?",body:"Kecepatan isi melambat drastis setelah 80% untuk melindungi baterai. Klaim 'penuh 30 menit' biasanya diukur dari kondisi hampir kosong dengan charger bawaan."},{heading:"Efek ke umur baterai",body:"Panas adalah musuh baterai. Fast charging yang sering dipakai penuh mempercepat penurunan kapasitas — untuk pemakaian santai semalaman, isi lambat justru lebih awet."}]},{slug:"vapor-chamber",title:"Vapor Chamber",desc:"Penyebar panas pipih agar performa HP stabil saat gaming.",kind:"Pendingin",example:"Contoh: Galaxy S25 Ultra",audience:["smartphones"],icon:"❄",artClass:"carbon",chapters:[{heading:"Cara kerjanya",body:"Vapor chamber adalah pelat pipih berisi cairan yang menguap saat kena panas chip lalu mengembun di area dingin — menyebar panas jauh lebih merata dibanding pelat grafit biasa. Galaxy S25 Ultra memakainya untuk menjaga performa game."},{heading:"Efek yang terasa",body:"HP tidak cepat throttling (menurunkan performa karena panas), jadi frame rate game lebih stabil di sesi panjang. Bodi tetap menghangat — hanya panasnya tersebar, bukan menumpuk di satu titik."},{heading:"Batasannya",body:"Vapor chamber membuang panas lebih baik, bukan menghilangkan panas. Di ruangan panas atau casing tebal, manfaatnya berkurang. Komponen ini juga menambah biaya, jadi absen di HP murah."}]},{slug:"usb-c",title:"USB-C",desc:"Satu colokan universal untuk isi daya, data, dan layar.",kind:"Konektivitas",example:"Contoh: iPhone 15 ke atas, Galaxy S series",audience:["smartphones","laptops"],icon:"🔗",artClass:"layers",chapters:[{heading:"Kenapa sekarang seragam?",body:"Regulasi Uni Eropa mewajibkan USB-C di perangkat baru, sehingga iPhone 15 ke atas ikut beralih dari Lightning. Satu kabel kini bisa dipakai lintas HP, laptop, dan aksesori."},{heading:"Bentuk sama, kecepatan beda",body:"Colokan USB-C yang sama bisa membawa kecepatan berbeda: USB 2.0 lambat di model dasar, USB 3/Thunderbolt kencang di model Pro. Kabelnya pun menentukan — kabel murah bisa membatasi kecepatan dan daya."},{heading:"Yang perlu diperhatikan",body:"Selalu cek spesifikasi port dan kabelnya, bukan bentuknya. Untuk transfer file besar atau monitor eksternal, pastikan kabel mendukung standar yang dibutuhkan."}]}];function c(a,b){if(void 0===a||void 0===b)return"Seri";let c=a-b;return 2>=Math.abs(c)?"Seri":c>0?"A":"B"}a.s(["buildDynamicComparison",0,function(a,b){return Array.from(new Set([...Object.keys(a.specs),...Object.keys(b.specs)])).map(c=>({label:c,a:a.specs[c]??"-",b:b.specs[c]??"-",scoreA:a.ratings[c],scoreB:b.ratings[c]}))},"buildVerdict",0,function(a,b,d){let e=0,f=0,g=0;for(let a of d){let b=c(a.scoreA,a.scoreB);"A"===b?e++:"B"===b?g++:f++}let h=d.length,i=e>g?a:e<g?b:null,j=0===h?"Tidak ada data spesifikasi untuk dibandingkan.":e>g?`${a} unggul di ${e} dari ${h} spesifikasi (${f} seri).`:e<g?`${b} unggul di ${g} dari ${h} spesifikasi (${f} seri).`:`Seimbang: masing-masing ${e} spesifikasi unggul dari ${h} (${f} seri).`;return{pemenang:i??"Seimbang",menang:e,seri:f,kalah:g,totalSpecs:h,message:j}},"categoriesMeta",0,{smartphones:{id:"smartphones",name:"Smartphones",tagline:"Bandingkan performa, kamera, baterai, dan fitur lainnya.",desc:"Temukan ponsel yang benar-benar cocok — bukan sekadar yang paling mahal. Kami membandingkan chip, layar, baterai, dan pengalaman kamera dari berbagai merek.",icon:"▯"},laptops:{id:"laptops",name:"Laptops",tagline:"Dari performa chip hingga daya tahan baterai, temukan yang terbaik untukmu.",desc:"Laptop untuk kerja, belajar, atau produksi konten. Kami bantu kamu memilih antara chipset, portabilitas, dan baterai yang paling cocok dengan aktivitasmu.",icon:"▱"},shoes:{id:"shoes",name:"Basketball Shoes",tagline:"Cek material, teknologi, dan performa untuk setiap gaya bermain.",desc:"Material upper, cushioning, dan stabilitas menentukan nyaman-tidaknya kamu di lapangan. Kami bandingkan sepatu basket terbaik untuk berbagai posisi dan gaya main.",icon:"⌁"}},"categoryIds",0,["smartphones","laptops","shoes"],"comparisons",0,[{slug:"iphone-16-pro-vs-galaxy-s25-ultra",category:"smartphones",searchKeywords:"iphone 16 pro galaxy s25 ultra apple samsung",tagline:"Dua flagship terbaru, dua pendekatan berbeda. Mana yang lebih cocok untukmu?",products:[{name:"iPhone 16 Pro",brand:"Apple",img:"/apple-iphone-16-pro-grey.jpg",score:92},{name:"Galaxy S25 Ultra",brand:"Samsung",img:"/samsung-galaxy-s25-ultra-grey.jpg",score:89}],specs:[{label:"Chipset",a:"A18 Pro",b:"Snapdragon 8 Elite for Galaxy",scoreA:94,scoreB:91},{label:"RAM",a:"8 GB",b:"12 GB",scoreA:80,scoreB:88},{label:"Kamera utama",a:"48 MP",b:"200 MP",scoreA:88,scoreB:94},{label:"Kamera zoom",a:"5x tele (12 MP)",b:"5x tele + 100x Space Zoom",scoreA:85,scoreB:95},{label:"Layar",a:'6.3" OLED 120 Hz',b:'6.9" AMOLED 120 Hz',scoreA:90,scoreB:93},{label:"Baterai",a:"±3.582 mAh",b:"5.000 mAh",scoreA:78,scoreB:88},{label:"Berat",a:"199 g",b:"218 g",scoreA:85,scoreB:80},{label:"Ketahanan",a:"IP68",b:"IP68",scoreA:90,scoreB:90}],chooseNotes:[["Kamu suka ekosistem Apple","Butuh performa video terbaik","Lebih suka ukuran yang compact"],["Butuh zoom kamera yang lebih jauh","Ingin S-Pen dan produktivitas lebih","Lebih suka layar yang lebih besar"]]},{slug:"macbook-air-m3-vs-thinkpad-t14s",category:"laptops",searchKeywords:"macbook air m3 thinkpad t14s apple lenovo",tagline:"Dua laptop ringan untuk mobilitas tinggi, masing-masing dengan keunggulan yang berbeda.",products:[{name:"MacBook Air M3",brand:"Apple",img:"/apple-macbook-air-m3.jpeg",score:90},{name:"ThinkPad T14s",brand:"Lenovo",img:"/thinkpad-t14s.avif",score:82}],specs:[{label:"Chipset",a:"Apple M3 (8-core GPU)",b:"Intel Core Ultra 7",scoreA:92,scoreB:85},{label:"RAM",a:"8–24 GB",b:"8–64 GB",scoreA:82,scoreB:90},{label:"Penyimpanan",a:"256 GB – 2 TB",b:"512 GB – 2 TB",scoreA:84,scoreB:88},{label:"Layar",a:'13.6" Liquid Retina',b:'14" WUXGA IPS',scoreA:88,scoreB:80},{label:"Baterai",a:"Hingga 18 jam",b:"Hingga 13 jam",scoreA:94,scoreB:85},{label:"Berat",a:"1,24 kg",b:"1,25 kg",scoreA:88,scoreB:87},{label:"Ports",a:"2× Thunderbolt",b:"2× USB-C + USB-A + HDMI",scoreA:78,scoreB:90},{label:"Sistem operasi",a:"macOS",b:"Windows 11 Pro",scoreA:85,scoreB:85}],chooseNotes:[["Butuh baterai paling awet","Fokus pada ekosistem Apple","Lebih suka desain yang tipis"],["Membutuhkan port lengkap (HDMI/USB-A)","Kamu bekerja di Windows","Butuh RAM besar untuk multitasking"]]},{slug:"lebron-22-vs-harden-vol-8",category:"shoes",searchKeywords:"nike lebron 22 adidas harden vol 8 basketball shoes",tagline:"Dua sepatu basketball dengan pendekatan cushioning dan dukungan yang berbeda.",products:[{name:"Nike LeBron 22",brand:"Nike",img:"/lebron-22.jpg",score:88},{name:"Adidas Harden Vol. 8",brand:"Adidas",img:"/harden-vol-8.png",score:84}],specs:[{label:"Upper",a:"Flyknit",b:"Knit + TPU",scoreA:88,scoreB:84},{label:"Cushioning",a:"Zoom Air + Air Max",b:"Boost + TPU frame",scoreA:90,scoreB:86},{label:"Court feel",a:"Responsif",b:"Nyaman & stabil",scoreA:88,scoreB:85},{label:"Berat",a:"± 360 g",b:"± 380 g",scoreA:86,scoreB:83},{label:"Cocok untuk",a:"Power forward",b:"Shooting guard",scoreA:84,scoreB:84}],chooseNotes:[["Butuh bantalan maksimal untuk jump tinggi","Posisi mainmu butuh dukungan ekstra","Suka fit terasa sporty dan ringkas"],["Butuh stabilitas saat gerakan lateral","Lebih suka bantalan empuk & nyaman","Sering bermain di posisi sayap"]]},{slug:"iphone-15-vs-pixel-8",category:"smartphones",searchKeywords:"iphone 15 pixel 8 apple google",tagline:"Dua pilihan entry flagship yang populer, dengan kekuatan yang sangat berbeda.",products:[{name:"iPhone 15",brand:"Apple",img:"/apple-iphone-15-blue.jpeg",score:86},{name:"Pixel 8",brand:"Google",img:"/google-pixel-8.jpg",score:80}],specs:[{label:"Chipset",a:"A16 Bionic",b:"Google Tensor G3",scoreA:88,scoreB:82},{label:"RAM",a:"6 GB",b:"8 GB",scoreA:76,scoreB:82},{label:"Kamera utama",a:"48 MP",b:"50 MP",scoreA:85,scoreB:86},{label:"Layar",a:'6.1" OLED 60 Hz',b:'6.2" OLED 120 Hz',scoreA:78,scoreB:88},{label:"Baterai",a:"±3.349 mAh",b:"4.575 mAh",scoreA:76,scoreB:86},{label:"Software",a:"iOS 17",b:"Android 14",scoreA:85,scoreB:85},{label:"Berat",a:"171 g",b:"187 g",scoreA:87,scoreB:83}],chooseNotes:[["Suka ekosistem Apple","Butuh performa video yang menyenangkan","Lebih suka ukuran yang ringkas"],["Gemar fotografi komputasional","Ingin layar 120 Hz di kelas ini","Suka fitur AI dari Google"]]}],"featuredMetrics",0,[{label:"Performa",icon:"⚙",a:94,b:90},{label:"Kamera",icon:"▣",a:96,b:88},{label:"Baterai",icon:"◴",a:90,b:87}],"getLearnItem",0,function(a){return b.find(b=>b.slug===a)},"learnItems",0,b,"overallVerdict",0,function(a,b,c,d){let e=Math.abs(c-d),f=0===e?"Seimbang":e<=3?"Tipis":e<=7?"Jelas":"Telak";if(0===e)return{pemenang:"Seimbang",gap:e,label:f,message:`Seimbang: skor total sama ${c} vs ${d}.`};let g=c>d?a:b;return{pemenang:g,gap:e,label:f,message:`${g} menang ${f.toLowerCase()}, skor ${c} vs ${d}.`}},"specGlossary",0,{Chipset:{simple:"Otak ponsel/laptop. Semakin baru dan kuat chipset, makin cepat buka aplikasi dan main game.",learnSlugs:["chip-3nm"]},RAM:{simple:"Memori kerja sementara. RAM besar = bisa buka banyak aplikasi sekaligus tanpa lambat.",learnSlugs:[]},"Kamera utama":{simple:"Kamera utama untuk foto sehari-hari. Semakin besar megapiksel, detail foto semakin tajam."},"Kamera zoom":{simple:"Kamera untuk foto dari jauh. Semakin besar kali zoom, objek jauh makin dekat terlihat.",learnSlugs:["kamera-periskop"]},Layar:{simple:"Tampilan layar. AMOLED/LTPO warnanya hidup, 120 Hz scrolling mulus tanpa gambar terputus.",learnSlugs:["amoled","ltpo","kaca-pelindung"]},Baterai:{simple:"Daya tahan baterai. Semakin besar, makin lama pemakaian sebelum isi ulang.",learnSlugs:["fast-charging"]},Berat:{simple:"Bobot perangkat. Semakin ringan, makin nyaman di genggam lama-lama."},Ketahanan:{simple:"Tahan air dan debu. IP68 artinya bisa terkena air tanpa langsung rusak.",learnSlugs:["ip68"]},Penyimpanan:{simple:"Ruang simpan file, foto, aplikasi. Semakin besar, makin sedikit hapus file."},Ports:{simple:"Jenis colokan. Thunderbolt cepat untuk transfer data; USB-A/HDMI port tradisional."},"Sistem operasi":{simple:"Perangkat lunak ponsel/laptop. macOS vs Windows punya kelebihan masing-masing."},Software:{simple:"Sistem operasi dan fitur bawaan. iOS dan Android punya keunggulan berbeda."},Upper:{simple:"Bahan luar sepatu. Flyknit ringan & lentur, Knit+TPU lebih kaku & stabil."},Cushioning:{simple:"Bantalan di tengah sepatu. Zoom Air responsif untuk lompat, Boost empuk untuk jarak jauh.",learnSlugs:["peba","carbon-fiber"]},"Court feel":{simple:"Kenyamanan di lapangan. Responsif = lincah, stabil = aman saat gerakan samping."},"Cocok untuk":{simple:"Posisi bermain yang cocok. Power forward butuh dukungan kuat, shooting guard butuh lincah."}},"specVerdict",0,c])}];

